require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);$flash='';$ft='ok';$newRecovery=[];$currentHash=hash('sha256',session_id());
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'password');try{if($act==='password'){$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$stored=(string)($ctx['user']['panel_password']??'');if(!password_verify($old,$stored))throw new DomainException('رمز فعلی اشتباه است.');if(mb_strlen($new)<10)throw new DomainException('رمز جدید حداقل ۱۰ کاراکتر باشد.');$pdo->prepare('UPDATE user SET panel_password=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$ctx['id']]);rxp_audit($pdo,$ctx,'profile.password',$ctx['id']);$flash='رمز تغییر کرد.';}elseif($act==='twofa'){$enabled=isset($_POST['enabled'])?1:0;if($ctx['role']==='super'&&!$enabled)throw new DomainException('2FA برای سوپرنماینده اجباری است.');$pdo->prepare('UPDATE user SET portal_2fa_enabled=? WHERE id=?')->execute([$enabled,$ctx['id']]);rxp_audit($pdo,$ctx,'profile.2fa',$ctx['id'],['enabled'=>$enabled]);$ctx['user']['portal_2fa_enabled']=$enabled;$flash='تنظیم 2FA ذخیره شد.';}elseif($act==='revoke'){$hash=(string)($_POST['session_hash']??'');$pdo->prepare('UPDATE reseller_sessions SET revoked_at=? WHERE session_hash=? AND reseller_id=?')->execute([time(),$hash,$ctx['id']]);rxp_audit($pdo,$ctx,'profile.session_revoke',$hash);if(hash_equals($currentHash,$hash)){session_destroy();header('Location:login.php');exit;}$flash='نشست لغو شد.';}elseif($act==='recovery_codes'){$pw=(string)($_POST['password']??'');if(!password_verify($pw,(string)$ctx['user']['panel_password']))throw new DomainException('رمز حساب اشتباه است.');$alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';$pdo->beginTransaction();$pdo->prepare('DELETE FROM reseller_recovery_codes WHERE reseller_id=?')->execute([$ctx['id']]);$ins=$pdo->prepare('INSERT INTO reseller_recovery_codes(reseller_id,code_hash,created_at,used_at) VALUES(?,?,?,NULL)');for($i=0;$i<10;$i++){$raw='';for($j=0;$j<10;$j++)$raw.=$alphabet[random_int(0,strlen($alphabet)-1)];$ins->execute([$ctx['id'],password_hash($raw,PASSWORD_DEFAULT),time()]);$newRecovery[]=substr($raw,0,5).'-'.substr($raw,5);}$pdo->commit();rxp_audit($pdo,$ctx,'profile.recovery_regenerate',$ctx['id']);$flash='کدهای بازیابی جدید ساخته شدند؛ فقط همین بار ذخیره کنید.';}elseif($act==='revoke_others'){$pdo->prepare('UPDATE reseller_sessions SET revoked_at=? WHERE reseller_id=? AND session_hash<>? AND revoked_at IS NULL')->execute([time(),$ctx['id'],$currentHash]);rxp_audit($pdo,$ctx,'profile.sessions_revoke_others',$ctx['id']);$flash='سایر نشست‌ها لغو شدند.';}}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$flash=rxp_public_exception_message($e, basename(__FILE__));$ft='err';}}
$q=$pdo->prepare('SELECT * FROM reseller_sessions WHERE reseller_id=? ORDER BY last_seen_at DESC LIMIT 50');$q->execute([$ctx['id']]);$sessions=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT COUNT(*) FROM reseller_recovery_codes WHERE reseller_id=? AND used_at IS NULL');$q->execute([$ctx['id']]);$recoveryCount=(int)$q->fetchColumn();$twofa=$ctx['role']==='super'||!empty($ctx['user']['portal_2fa_enabled']);rxp_layout_start($ctx,'حساب و امنیت','profile.php');rxp_flash($flash,$ft);?>
<h1 class="rxp-title">حساب و امنیت</h1><div class="rxp-grid"><div class="rxp-stat"><b><?=rxp_h($ctx['id'])?></b><span>آیدی</span></div><div class="rxp-stat"><b><?=rxp_h($ctx['role'])?></b><span>نقش</span></div><div class="rxp-stat"><b><?=$twofa?'فعال':'خاموش'?></b><span>2FA تلگرامی</span></div></div>
<div class="rxp-card"><h2>تأیید دومرحله‌ای</h2><form method="post" class="rxp-form"><input type="hidden" name="action" value="twofa"><label class="rxp-muted"><input type="checkbox" name="enabled" <?=$twofa?'checked':''?> <?=$ctx['role']==='super'?'disabled':''?>> ارسال کد ۶ رقمی تلگرام در هر ورود</label><?php if($ctx['role']==='super'):?><input type="hidden" name="enabled" value="1"><span class="rxp-badge">اجباری برای سوپرنماینده</span><?php endif;?><button class="rxp-btn">ذخیره</button></form></div>
<?php if($newRecovery):?><div class="rxp-card"><h2>کدهای بازیابی جدید — فقط یک بار</h2><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;direction:ltr"><?php foreach($newRecovery as$c):?><code style="padding:8px;background:var(--surface-2);text-align:center"><?=rxp_h($c)?></code><?php endforeach;?></div><p class="rxp-flash err">این کدها را آفلاین نگهداری کنید؛ هر کد فقط یک بار قابل استفاده است.</p></div><?php endif;?>
<div class="rxp-card"><h2>کدهای بازیابی (<?=$recoveryCount?> کد استفاده‌نشده)</h2><form method="post" class="rxp-form"><input type="hidden" name="action" value="recovery_codes"><div class="rxp-field"><label>برای ساخت/جایگزینی، رمز فعلی را وارد کنید</label><input type="password" name="password" required></div><button class="rxp-btn red" onclick="return confirm('تمام کدهای قبلی باطل شوند؟')">تولید ۱۰ کد جدید</button></form></div>
<div class="rxp-card"><h2>تغییر رمز</h2><form method="post" class="rxp-form"><input type="hidden" name="action" value="password"><div class="rxp-field"><label>رمز فعلی</label><input type="password" name="old_password" required></div><div class="rxp-field"><label>رمز جدید</label><input type="password" name="new_password" minlength="10" required></div><button class="rxp-btn">تغییر رمز</button></form></div>
<div class="rxp-card"><h2>نشست‌های فعال</h2><form method="post" style="margin-bottom:10px"><input type="hidden" name="action" value="revoke_others"><button class="rxp-btn red">خروج از سایر دستگاه‌ها</button></form><div class="rxp-table-wrap"><table class="rxp-table"><tr><th>دستگاه</th><th>IP</th><th>ایجاد</th><th>آخرین فعالیت</th><th>وضعیت</th><th></th></tr><?php foreach($sessions as$s):$current=hash_equals($currentHash,(string)$s['session_hash']);?><tr><td><?=rxp_h(mb_substr((string)$s['ua_label'],0,80))?> <?=$current?'<span class="rxp-badge">فعلی</span>':''?></td><td><?=rxp_h($s['ip'])?></td><td><?=date('Y/m/d H:i',(int)$s['created_at'])?></td><td><?=date('Y/m/d H:i',(int)$s['last_seen_at'])?></td><td><?=$s['revoked_at']?'لغوشده':((int)$s['expires_at']<time()?'منقضی':'فعال')?></td><td><?php if(!$s['revoked_at']&&(int)$s['expires_at']>=time()):?><form method="post"><input type="hidden" name="action" value="revoke"><input type="hidden" name="session_hash" value="<?=rxp_h($s['session_hash'])?>"><button class="rxp-btn red">لغو</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php rxp_layout_end();
